public int alpha(int x, int y){
  x *= 2;
  y -= 2;
  return x - y;
}

public int beta(int z){
  z++;
  z = alpha(z, z / 2);
  return z;
}

public void gamma(){
  int x = 2;
  System.out.print( alpha(x, x + 2) );
  System.out.print( " " + x );
}

public void delta(){
  int x = beta(3);
  System.out.print( x );
}

